import {featurePrompt} from './guidance-ui.js';
import {BMAPS,BPOINTS,BPOINT_BY_ID,BACTIONS,BEVENTS,BEVENT_BY_ID} from './beyond-data.js';
import {ITEMS,REGIONS} from './data.js';
import {RESIDENTS} from './expansion-data.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,id,label,reason='')=>`<button data-action="${action}" data-id="${esc(id)}" ${reason?'disabled':''}>${esc(label)}</button>`;
const goods=o=>Object.entries(o||{}).filter(([,n])=>n>0).map(([id,n])=>esc(ITEMS[id]?.name||id)+' × '+n).join('、')||'无需材料';
const card=(title,body,cls='')=>`<section class="b-card ${cls}"><h3>${esc(title)}</h3>${body}</section>`;
export function renderBeyondWorld(e){return `<section class="b-world"><div class="b-heading"><div><span class="b-eyebrow">通向远方</span><h3>边境与航路</h3></div>${button('bOpen','','边境手册')}</div><div class="b-world-grid">${Object.entries(BMAPS).map(([id,d])=>{const open=e.b.unlocked[id],why=e.beyondUnlockReason(id);return `<article class="b-destination" style="--b-accent:${d.color}"><span class="b-map-mark">${d.mark}</span><h4>${d.name}</h4><p>${d.purpose}</p><small>${open?'通路已开放':esc(why||'已具备条件：带材料到入口修路')}</small>${button('bRegion',id,open?'查看地区':'查看通路')}</article>`;}).join('')}</div></section>`;}
export function renderBeyondTeaser(e){const ready=Object.entries(BMAPS).find(([id])=>!e.b.unlocked[id]&&!e.beyondUnlockReason(id));const active=e.bactive()[0];return `<div class="b-teaser"><div><b>${active?active.name:ready?'远处有一条可修的路':'边境来信'}</b><span>${active?esc(e.beventLocation(active.id)?.name):ready?ready[1].name+' · 从'+REGIONS[ready[1].parent].name+'前往':'在林场、船坞与新的聚落中寻找家园的下一步。'}</span></div>${button('bOpen','','查看边境手册')}</div>`;}
export function renderBeyond(e,ui={}){const region=BMAPS[ui.region]?ui.region:e.b.focus,def=BMAPS[region],view=ui.view||'overview';let body='';
 if(view==='entrance'||!e.b.unlocked[region]&&!['events','life','jobs','ledger'].includes(view)){const why=e.beyondUnlockReason(region);body=card(def.name,`<p class="b-lead">${def.purpose}</p><div class="b-facts"><div><small>入口</small><strong>${REGIONS[def.parent].name}</strong></div><div><small>环境</small><strong>${def.risk}</strong></div></div><p>修路材料：${goods(def.cost)}</p><p class="b-reason">${esc(why||'条件已具备，带材料到入口修复通路。')}</p><div class="b-actions">${button('bParent',region,'前往入口所在地区',e.districtTravelReason(def.parent))}${button('bUnlock',region,'修复通路',why||e.s.region!==def.parent?'请先前往入口':'')}</div><p class="b-muted">进入地区后，跟随金色路标找到入口。修路会实际消耗上述材料。</p>`);}
 else if(view==='events')body=events(e,ui);
 else if(view==='point'){const p=BPOINT_BY_ID[ui.point]||BPOINTS.find(p=>p.region===region);body=point(e,p,ui);}
 else if(view==='jobs')body=jobs(e);
 else if(view==='storage')body=storage(e,region);
 else if(view==='life')body=life(e);
 else if(view==='ledger')body=card('家园与边境的记录',e.b.ledger.length?`<ol class="b-log">${e.b.ledger.map(l=>`<li><small>第${l.day}天 · ${esc(REGIONS[l.region]?.name||'家园')}</small><p>${esc(l.text)}</p></li>`).join('')}</ol>`:'<p>修通道路后，新的变化会记在这里。</p>');
 else body=card(def.name,`<p class="b-lead">${def.purpose}</p><p>${def.risk}</p><div class="b-actions">${button('bTravel',region,e.s.region===region?'已在本地区':'前往地区',e.s.region===region?'已抵达':e.districtTravelReason(region))}${button('bView','storage','当地仓库')}${button('bView','jobs','工作与运输')}</div><div class="b-point-grid">${BPOINTS.filter(p=>p.region===region).map(p=>`<button class="b-place" data-action="bPoint" data-id="${p.id}"><span>${e.bpoint(p.id).count?'●':'◇'}</span><div><strong>${p.name}</strong><small>${p.purpose}</small></div></button>`).join('')}</div>`);
 if(view==='point'&&e.b.unlocked[region]){const p=BPOINT_BY_ID[ui.point]||BPOINTS.find(p=>p.region===region);return `<div class="simple-site"><header class="simple-site-header"><small>${def.name} · 现场工作</small>${button('gJournal','','返回当前任务')}</header>${featurePrompt(e,'b:'+p.id)}${body}<details class="simple-site-other"><summary>这里还有什么</summary><div>${button('bView','overview','地区事务')}${button('bView','jobs','正在进行的工作')}${button('bView','storage','当地仓库')}</div></details></div>`;}
 return `<div class="b-shell"><nav class="b-nav" aria-label="边境手册分类"><div class="b-eyebrow">远行之后 · 仍有归处</div>${Object.entries(BMAPS).map(([id,d])=>`<button class="${region===id?'selected':''}" data-action="bRegion" data-id="${id}"><i style="color:${d.color}">${d.mark}</i><span>${d.name}<small>${e.b.unlocked[id]?'通路开放':'待探索'}</small></span></button>`).join('')}<div class="b-nav-divider"></div>${[['events','边境来信'],['jobs','工作与运输'],['life','邻里与伙伴'],['ledger','家园记事']].map(([id,n])=>button('bView',id,n)).join('')}</nav><main class="b-detail" tabindex="-1">${body}</main></div>`;
}
function point(e,p,ui){const active=e.b.jobs.find(j=>j.point===p.id);const state=e.bpoint(p.id);let detail=card(p.name,`<p class="b-lead">${p.purpose}</p><div class="b-actions">${button('bTrack',p.id,'标记在地图上')}${button('bTravel',p.region,'前往'+BMAPS[p.region].name,e.s.region===p.region?'已在本地区':e.districtTravelReason(p.region))}</div>${active?`<div class="b-progress"><b>${BACTIONS[p.id].find(a=>a.key===active.key)?.label}</b><span>还需${Math.ceil(active.remaining)}游戏分钟 · 关闭手册后时间继续</span></div>`:''}<div class="b-action-list">${BACTIONS[p.id].map(a=>{const q=e.bquote(p.id,a.key),done=state.flags[a.key],removable=(a.module||a.boat)&&done;return `<article><div><h4>${esc(a.label)}</h4><p>${esc(a.note||'完成后物资留在当地仓库，供后续建设与远征使用。')}</p><div class="b-cost"><span>投入：${goods(q.cost)}</span><span>工时：${a.minutes}分钟</span>${Object.keys(q.out||{}).length?`<span>产出：${goods(q.out)}</span>`:''}</div>${q.reason?`<p class="b-reason">${esc(q.reason)}</p>`:''}</div>${removable?button('bRemove',p.id+':'+a.key,'拆下 · 返木3布1'):button('bAct',p.id+':'+a.key,done&&a.repeat===undefined&&!a.choice?'已完成':'安排工作',q.reason)}</article>`;}).join('')}</div>`);
 if(p.id==='pinewood_coop')detail+=workers(e);if(p.id==='frost_weather'&&e.b.forecast.length)detail+=card('已记录的预报',e.b.forecast.map(f=>`<p>第${f.day}天 · ${f.weather}</p>`).join(''));if(p.id==='archive_council')detail+=card('正在建设的明天',Object.entries(e.b.vision).map(([k,n])=>`<p>${{self:'自给',guest:'好客',knowledge:'求知'}[k]} · ${n}/3期</p>`).join(''));if(p.id==='shipyard_ferry'||p.id==='shipyard_post')detail+=transport(e);if(p.id==='frost_rye'&&e.b.contract)detail+=contract(e);return detail;}
function events(e,ui){const id=BEVENT_BY_ID[ui.event]?ui.event:e.bactive()[0]?.id||BEVENTS.find(x=>e.b.unlocked[x.region])?.id||BEVENTS[0].id,d=BEVENT_BY_ID[id],r=e.b.records[id],q=e.bstepQuote(id);return `<div class="b-heading"><div><span class="b-eyebrow">消息不会在离线时过期</span><h3>边境来信</h3></div><small>正在处理 ${e.bactive().length+e.activeEvents().length}/2</small></div><div class="b-event-list">${BEVENTS.map(x=>{const v=e.b.records[x.id];return `<button class="${x.id===id?'selected':''}" data-action="bEvent" data-id="${x.id}"><b>${x.name}</b><small>${v?.status==='resolved'?'已完成':v?.status==='active'?'进行中':v?.status==='paused'?'已暂缓':e.b.unlocked[x.region]?BMAPS[x.region].name:'等待探索'}</small></button>`;}).join('')}</div>${card(d.name,`<p class="b-lead">${d.story}</p><div class="b-promise"><small>办妥后</small><p>${d.reward}</p></div>${!r||r.status!=='active'?`<p class="b-reason">${esc(e.beventReason(id)||'现在可以接下这件事。')}</p>${button('bAccept',id,r?.status==='paused'?'继续这件事':r?.status==='resolved'?'再赴约定':'接下这件事',e.beventReason(id))}`:!r.choice?`<div class="b-choices">${d.choices.map(c=>`<article><h4>${c.label}</h4><p>${c.desc}</p><small>第一步投入：${goods(c.cost)}</small>${button('bChoose',id+':'+c.id,'选择这个安排')}</article>`).join('')}</div>`:`<p>当前安排：${d.choices.find(c=>c.id===r.choice)?.label}</p><ol class="b-steps">${d.steps.map((s,i)=>`<li class="${i===r.stage?'current':i<r.stage?'done':''}">${i<r.stage?'✓ ':''}${s.title}</li>`).join('')}</ol><div class="b-progress"><b>${esc(q.title)}</b><span>${r.remaining?'还需'+Math.ceil(r.remaining)+'游戏分钟，关闭手册后继续':'投入：'+goods(q.cost)+' · 工时'+q.minutes+'分钟'}</span></div><p class="b-reason">${esc(q.reason||'已到达，可开始这一步。')}</p><div class="b-actions">${button('bEventTrack',id,'标记下一步')}${button('bEventTravel',id,'前往所在地',e.districtTravelReason(e.beventLocation(id)?.region))}${button('bPerform',id,'进行这一步',q.reason)}</div>`}${r?.status==='active'?`<div class="b-actions">${button('bPause',id,'暂缓 · 保留进度')}${!r.paid&&r.stage===0?button('bResetChoice',id,'重新考虑方案'):''}</div>`:''}`)}`;}
function jobs(e){return card('正在进行的工作',e.b.jobs.length?e.b.jobs.map(j=>{const p=BPOINT_BY_ID[j.point],a=BACTIONS[j.point].find(a=>a.key===j.key);return `<article class="b-job"><div><strong>${a.label}</strong><p>${p.name} · 剩余${Math.ceil(j.remaining)}游戏分钟</p><small>完成后直接存入${BMAPS[p.region].name}仓库</small></div>${button('bCancel',j.id,'取消 · 返还一半材料')}</article>`;}).join(''):'<p>各地设施最多同时安排三项工作。菜单中时间暂停，离开手册后可以去种田或探索。</p>')+transport(e);}
function storage(e,region){const here=e.s.region===region,near=here&&Math.hypot(e.s.player.x-220,e.s.player.y-570)<130,store=e.b.stores[region];return card(BMAPS[region].name+'仓库',`<p>工作产出与奖励都放在这里。取用需要站在入口旁的仓库附近。</p>${button('bStoreTrack',region,'标记仓库')}${button('bRest','','休整一小时 · 饥饿−5',!near?'先靠近当地仓库':'')}<div class="b-storage">${[...new Set([...Object.keys(store),...Object.keys(e.s.inventory).filter(k=>!ITEMS[k].protected)])].filter(k=>ITEMS[k]).map(k=>`<article><div><strong>${ITEMS[k].name}</strong><small>本仓 ${store[k]||0} · 随身 ${e.s.inventory[k]||0}</small><p>${ITEMS[k].desc}</p></div><div class="b-actions">${button('bDeposit',k,'存入',!near||!e.qty(k)?'不可存入':'')}${button('bWithdraw',k,'取1份',!near||!store[k]?'不可取出':'')}${button('bWithdrawAll',k,'取一批',!near||!store[k]?'不可取出':'')}</div></article>`).join('')||'<p>仓库还没有物资。</p>'}</div>`);}
function transport(e){const available=e.bflag('shipyard_ferry','service')&&['farm','shipyard'].includes(e.s.region);return card('河道船班',`<p>农场与船坞之间运输。两条班次；${e.b.boat.includes('cargo')?'加装货舱后每船12份':'每船6份'}；基础运费1干粮，条约有效时免运费。</p>${e.b.shipments.map(s=>`<p class="b-progress">${s.mail?'邮袋':goods(s.payload)} → ${REGIONS[s.to].name} · 剩余${Math.ceil(s.remaining)}分钟</p>`).join('')}<div class="b-actions"><label>货物<select id="b-cargo">${['wood','cloth','bread','herb','resin','salt','filterFabric','rye'].map(id=>`<option value="${id}">${ITEMS[id].name}</option>`).join('')}</select></label>${button('bShip','','装载一批货物',available?'':'需恢复航线，并在农场或船坞操作')}${button('bMail','','投递另一封信',available&&e.b.records.mailbag?.completed&&!e.b.mail.sent.includes('remaining')&&!e.b.shipments.some(s=>s.mail)?'':'邮件尚不可投递或已送达')}</div>${e.b.mail.receipts.map(s=>`<p class="b-muted">${esc(s)}</p>`).join('')}${!e.b.treaty&&e.b.records.bordertalk?.status==='resolved'?button('bService','renewTreaty','重新商谈河道约定'):''}${e.b.treaty?`<p>河道条约有效至第${e.b.treaty.until}天。${e.b.treaty.worker?'守卫：'+RESIDENTS[e.b.treaty.worker]?.name:''}</p>`:''}`);}
function workers(e){return card('岗位安排',`<p>外派居民需要床位、每日工作餐和休息。林场每四小时额外消耗当地仓库1干粮，产出木材3与松脂1。</p>${e.c.residents.map(r=>`<article class="b-job"><div><strong>${RESIDENTS[r.id]?.name||r.id}</strong><p>${esc(r.status)} · 疲劳${Math.round(r.fatigue||0)}</p><small>${e.b.workers[r.id]?{pinewood:'林场互助',station:'驻站制图',field:'随队制图',treaty:'河道守卫'}[e.b.workers[r.id]]:'家园或原地区岗位'}</small></div><div class="b-actions">${button('bWorker',r.id+':pinewood','派往林场',!e.bflag('pinewood_coop','service')?'互助站未恢复':'')}${r.id==='cartographer'?button('bWorker',r.id+':station','驻站制图')+button('bWorker',r.id+':field','随队向导'):''}${button('bWorker',r.id+':home','返回家园')}</div></article>`).join('')}`);}
function contract(e){return card('种源合同',`<p>第${e.b.contract.due}天交黑麦4，换食盐6。${e.s.day>e.b.contract.due?'已逾期：可先延期或结束合同，不会追加债务。':'只按游戏日计时。'}</p><div class="b-actions">${button('bService','contract','交付黑麦',e.s.region!=='frost'?'请到白霜站交付':'')}${button('bService','extend','延期四天',e.b.contract.extended?'已延期过':'')}${button('bService','cancelContract','结束合同 · 保留种子')}</div>`);}
function life(e){return workers(e)+card('新邻里',`<p>家园已接纳${e.b.family}户家庭；已接回${e.b.evacuated}批撤离者。家庭占用床位，留下的居民仍需要每日工作餐。</p><p>可供工作居民使用的床位：${e.residentsCapacity()}；目前居民：${e.c.residents.length}。</p><div class="b-actions">${button('bService','family','邻里互助 · 干粮1换木材',!e.b.family?'先完成团聚或撤离委托':'')}${button('bService','visitor','招待访客 · 干粮2换食盐3',!(e.b.benefits.visitorUntil>=e.s.day)?'聚会后会有访客':'' )}</div>${e.b.lastReport?`<p>${e.b.lastReport.text}</p>`:''}`)+card('麦穗的安排',`<p>警戒每天消耗1干粮，提前察觉附近敌人；等待会留在原地，回家会离开远征队。</p><div class="b-actions">${[['follow','跟随'],['guard','警戒'],['wait','等待'],['home','回家']].map(([id,n])=>button('bDog',id,n,!e.f.dog.rescued?'先救回麦穗':!e.b.benefits.dogOrders?'先调查断桥':'')).join('')}</div>`)+(e.b.contract?contract(e):'')+transport(e);}
export function handleBeyondAction(action,buttonEl,ctx){if(!action.startsWith('b')||!['bOpen','bRegion','bView','bPoint','bParent','bUnlock','bTravel','bTrack','bAct','bRemove','bEvent','bAccept','bPause','bChoose','bResetChoice','bPerform','bEventTrack','bEventTravel','bCancel','bDeposit','bWithdraw','bWithdrawAll','bStoreTrack','bRest','bWorker','bDog','bService','bShip','bMail'].includes(action))return false;const {engine:e,ui,showMenu,closeMenu,renderMenu,save,toast,root}=ctx,id=buttonEl.dataset.id||'';let ok=true;
 const open=args=>showMenu('beyond',args);if(action==='bOpen'){const target=e.beyondTarget();open(e.b.track?.startsWith('event:')?{event:e.b.track.slice(6),view:'events'}:target?{region:target.region,point:e.b.track,view:'point'}:{region:e.b.focus,view:'overview'});return true;}if(action==='bRegion'){e.b.focus=id;open({region:id,view:e.b.unlocked[id]?'overview':'entrance'});return true;}if(action==='bView'){open({view:id});return true;}if(action==='bPoint'){open({point:id,region:BPOINT_BY_ID[id].region,view:'point'});return true;}if(action==='bEvent'){open({event:id,view:'events'});return true;}
 if(action==='bParent'){const d=BMAPS[id];ok=e.travel(d.parent);if(ok){e.b.track=null;ctx.rebuildUI.target={region:d.parent,...d.gate,name:d.name+'入口'};closeMenu();}}
 else if(action==='bTravel'||action==='bEventTravel'){ok=e.travel(action==='bTravel'?id:e.beventLocation(id).region);if(ok){if(action==='bEventTravel')e.b.track='event:'+id;closeMenu();}}
 else if(action==='bTrack'||action==='bEventTrack'){if(e.guidance&&action==='bTrack')e.guidance.focus='b:'+id;e.b.track=action==='bTrack'?id:'event:'+id;e.d.track=null;closeMenu();}
 else if(action==='bStoreTrack'){e.b.track=null;e.d.track=null;ctx.rebuildUI.target={region:id,x:220,y:570,name:BMAPS[id].name+'仓库'};closeMenu();}
 else if(action==='bUnlock')ok=e.unlockBeyond(id);
 else if(action==='bAct'){const [p,k]=id.split(':');ok=e.bact(p,k);}
 else if(action==='bRemove'){const [p,k]=id.split(':');ok=e.bremove(p,k);}
 else if(action==='bAccept')ok=e.baccept(id);
 else if(action==='bPause')ok=e.bpause(id);
 else if(action==='bChoose'){const [p,k]=id.split(':');ok=e.bchoose(p,k);}
 else if(action==='bResetChoice'){const r=e.b.records[id];ok=!!r&&!r.paid&&r.stage===0;if(ok)r.choice=null;}
 else if(action==='bPerform')ok=e.bperform(id);
 else if(action==='bCancel')ok=e.bcancel(id);
 else if(action==='bDeposit'||action==='bWithdraw'||action==='bWithdrawAll')ok=e.btransfer(id,action==='bDeposit',action==='bWithdraw'?1:99);
 else if(action==='bRest')ok=e.brest();
 else if(action==='bWorker'){const [p,k]=id.split(':');ok=e.bassign(p,k==='home'?null:k);}
 else if(action==='bDog')ok=e.bdog(id);
 else if(action==='bService')ok=e.bservice(id);
 else if(action==='bShip')ok=e.bship(root.querySelector('#b-cargo')?.value||'wood',e.b.boat.includes('cargo')?12:6);
 else if(action==='bMail')ok=e.bship('bread',1,true);
 if(!ok)toast('还未满足条件。检查位置、材料、床位和正在进行的工作。','warn');if(ok)save();if(!['bParent','bTravel','bEventTravel','bTrack','bEventTrack','bStoreTrack'].includes(action)||!ok)renderMenu();return true;}
